  check(\"String control \" + JSON.stringify([v,opts]), () => new Range(c.value,opts).test(v))
  check(\"SemVer input \" + JSON.stringify([v,opts]), () => new Range(c,opts).test(new SemVer(v)))
  check(\"satisfies Comparator \" + JSON.stringify([v,opts]), () => satisfies(v,c,opts))
