  for (const r of [\"1.2.3-alpha\", \"*\", \"* || 1.2.3-alpha\", \"1.2.3-alpha || *\", \">=0.0.0 || 1.2.3-alpha\"]) {
    check(\"OR \" + JSON.stringify([r,opts]), () => { const x = new Range(r,opts); return {normalized:x.range,pre:x.test(\"1.2.3-alpha\"),stable:x.test(\"1.2.3\")} })
  }
}
for (const [a,b,w] of [
 [\">=1.2.3-alpha <2.0.0\", \"1.2.3-beta\",\"1.2.3-beta\"],
 [\">=1.2.3-alpha <2.0.0\", \"1.2.3\",\"1.2.3\"],
